    // flight; cp.async copies land directly in shared memory while the
    // FMA loop consumes an older tile.
    __shared__ __align__(16) float As[STAGES][BK][BM + SMPAD];  // A staged transposed
    __shared__ __align__(16) float Bs[STAGES][BK][BN + SMPAD];
    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;
    const int tid = threadIdx.x;
    const int warpId = tid >> 5;
    const int lane = tid & 31;
    // Warp-level tiling: 2x4 warps, each warp computes a 64x32 sub-tile.
    // Thread-level tiling: each thread computes an 8x8 register tile.
    const int threadRow = (warpId >> 2) * 64 + (lane >> 2) * TM;
    const int threadCol = (warpId & 3) * 32 + (lane & 3) * TN;
    const int kStart = blockIdx.z * chunk;
    const int kEnd = min(kStart + chunk, K);
    float accum[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            accum[i][j] = 0.0f;
    const bool vecOK = ((K & 3) == 0) && ((N & 3) == 0);
    if (vecOK)
    {
        // cp.async multi-stage pipeline: global->shared copies are issued
        // asynchronously (STAGES-1 K-tiles in flight), eliminating the
        // register staging of the previous double buffer and hiding
        // global memory latency across several K-tiles of FMA work.
        const int br = tid >> 5;        // B row (K dim): 0..7
        const int bc = (tid & 31) * 4;  // B col (N dim): 0,4,...,124
        // A loader: 4 scalar async copies per thread; the transposed
        // shared-memory staging is bank-conflict-free.
        int aRow[(BM * BK) / NTHREADS];
        int aCol[(BM * BK) / NTHREADS];
        #pragma unroll
        for (int i = 0; i < (BM * BK) / NTHREADS; ++i)
        {
            int idx = tid + i * NTHREADS;
            aRow[i] = idx / BK;   // A row (M dim): 0..127
            aCol[i] = idx % BK;   // A col (K dim): 0..7
        }
        // Issue all global->shared async copies for one K-tile, then
        // commit them as one group.
        auto issueTile = [&](int stage, int k)
        {
            #pragma unroll
            for (int i = 0; i < (BM * BK) / NTHREADS; ++i)
            {
                int gm = blockRow + aRow[i];
                int gk = k + aCol[i];
                bool p = (gm < M) && (gk < kEnd);
                const float* src = p ? (A + ((long long)gm * K + gk)) : A;
                cp_async4(&As[stage][aCol[i]][aRow[i]], src, p);
            }
            int gk2 = k + br;
            int gn = blockCol + bc;
            bool p = (gk2 < kEnd) && (gn < N);
            const float* src = p ? (B + ((long long)gk2 * N + gn)) : B;
            cp_async16(&Bs[stage][br][bc], src, p);
            cp_async_commit();
        };
        // Prologue: fill the first STAGES-1 pipeline stages.
        #pragma unroll
        for (int s = 0; s < STAGES - 1; ++s)
        {
            int k = kStart + s * BK;
            if (k < kEnd)
                issueTile(s, k);
            else
                cp_async_commit();  // empty group keeps wait counts consistent
        }
        int readStage = 0;
        int kLoad = kStart + (STAGES - 1) * BK;
        for (int k = kStart; k < kEnd; k += BK)
        {
            // Wait until the oldest in-flight K-tile has landed in
            // shared memory, then make it visible to the whole block.
