            __syncthreads();
            // Prefetch the K-tile STAGES-1 iterations ahead into the
            // stage freed by the tile consumed in the previous
            // iteration (the __syncthreads above guarantees all
            // threads are done reading it).
            int writeStage = readStage + STAGES - 1;
            if (writeStage >= STAGES) writeStage -= STAGES;
            if (kLoad < kEnd)
                issueTile(writeStage, kLoad);
            else
                cp_async_commit();
            kLoad += BK;
            // Compute on the current tile while the async copies are
            // in flight. Both operands are read from shared memory as
            // aligned float4s.
            #pragma unroll
            for (int kk = 0; kk < BK; ++kk)
            {
                const float4 a0 = *reinterpret_cast<const float4*>(&As[readStage][kk][threadRow]);
                const float4 a1 = *reinterpret_cast<const float4*>(&As[readStage][kk][threadRow + 4]);
                const float4 b0 = *reinterpret_cast<const float4*>(&Bs[readStage][kk][threadCol]);
                const float4 b1 = *reinterpret_cast<const float4*>(&Bs[readStage][kk][threadCol + 4]);
                float aReg[TM] = {a0.x, a0.y, a0.z, a0.w, a1.x, a1.y, a1.z, a1.w};
                float bReg[TN] = {b0.x, b0.y, b0.z, b0.w, b1.x, b1.y, b1.z, b1.w};
                #pragma unroll
                for (int i = 0; i < TM; ++i)
                    #pragma unroll
                    for (int j = 0; j < TN; ++j)
                        accum[i][j] += aReg[i] * bReg[j];
            }
            readStage = (readStage + 1) & (STAGES - 1);
        }
        cp_async_wait<0>();
    }
    else
    {
        // Scalar fallback path (unaligned shapes): single-buffered.
        for (int k = kStart; k < kEnd; k += BK)
        {
            #pragma unroll
            for (int i = 0; i < (BM * BK) / NTHREADS; ++i)
            {
                int idx = tid + i * NTHREADS;
                int r = idx / BK;
                int c = idx % BK;
                int gm = blockRow + r;
                int gk = k + c;
                As[0][c][r] = (gm < M && gk < kEnd)
                            ? A[(long long)gm * K + gk] : 0.0f;
            }
            #pragma unroll
            for (int i = 0; i < (BK * BN) / NTHREADS; ++i)
            {
                int idx = tid + i * NTHREADS;
                int r = idx / BN;
                int c = idx % BN;
                int gk = k + r;
                int gn = blockCol + c;
                Bs[0][r][c] = (gk < kEnd && gn < N)
                            ? B[(long long)gk * N + gn] : 0.0f;
            }
            __syncthreads();
            #pragma unroll
            for (int kk = 0; kk < BK; ++kk)
            {
                float aReg[TM];
                float bReg[TN];
                #pragma unroll
                for (int i = 0; i < TM; ++i) aReg[i] = As[0][kk][threadRow + i];
                #pragma unroll
                for (int j = 0; j < TN; ++j) bReg[j] = Bs[0][kk][threadCol + j];
                #pragma unroll
                for (int i = 0; i < TM; ++i)
                    #pragma unroll
                    for (int j = 0; j < TN; ++j)
                        accum[i][j] += aReg[i] * bReg[j];
            }
            __syncthreads();
        }
    }
    // Accumulate this block's partial K-slice into the output.
    #pragma unroll
    for (int i = 0; i < TM; ++i)
    {
        int gm = blockRow + threadRow + i;
        if (gm < M)
        {
            #pragma unroll
            for (int j = 0; j < TN; ++j)
            {
                int gn = blockCol + threadCol + j;
                if (gn < N)
