    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM, splits);
    auto stream = at::cuda::getCurrentCUDAStream();
    matmul_splitk_kernel<<<grid, block, 0, stream>>>(
        Ac.data_ptr<float>(), Bc.data_ptr<float>(), C.data_ptr<float>(),
        M, N, K, chunk);
    return C;
}
